16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.util.*;
25	
26	/**
27	 * Simple JavaBean domain object representing an owner.
28	 *
29	 * @author Ken Krebs
30	 * @author Juergen Hoeller
31	 * @author Sam Brannen
32	 * @author Michael Isvy
33	 */
34	@Entity
35	@Table(name = "owners")
36	public class Owner extends Person {
37	    @Column(name = "address")
38	    @NotEmpty
39	    private String address;
40	
41	    @Column(name = "city")
42	    @NotEmpty
43	    private String city;
44	
45	    @Column(name = "telephone")
46	    @NotEmpty
47	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be E.164 form: '+' followed by 8 to 15 digits")
48	    private String telephone;
49	
50	    @Column(name = "email")
51	    private String email;
52	
53	    @Column(name = "registration_date", columnDefinition = "DATE")
54	    private java.time.LocalDate registrationDate;
55	
56	    @Column(name = "customer_code")
57	    private String customerCode;
58	
59	    @Column(name = "household_id")
60	    private String householdId;
61	
62	    @Column(name = "namesake_count")
63	    private Integer namesakeCount;
64	
65	    @Column(name = "bulk_signup_warning")
66	    private boolean bulkSignupWarning;
67	
68	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
69	    private Set<Pet> pets;
70	
71	    public String getAddress() {
72	        return this.address;
73	    }
74	
75	    public void setAddress(String address) {
76	        this.address = address;
77	    }
78	
79	    public String getCity() {
80	        return this.city;
81	    }
82	
83	    public void setCity(String city) {
84	        this.city = city;
85	    }
86	
87	    public String getTelephone() {
88	        return this.telephone;
89	    }
90	
91	    public void setTelephone(String telephone) {
92	        this.telephone = telephone;
93	    }
94	
95	    public String getEmail() {
96	        return this.email;
97	    }
98	
99	    public void setEmail(String email) {
100	        this.email = email;
101	    }
102	
103	    public java.time.LocalDate getRegistrationDate() {
104	        return this.registrationDate;
105	    }
106	
107	    public void setRegistrationDate(java.time.LocalDate registrationDate) {
108	        this.registrationDate = registrationDate;
109	    }
110	
111	    public String getCustomerCode() {
112	        return this.customerCode;
113	    }
114	
115	    public void setCustomerCode(String customerCode) {
116	        this.customerCode = customerCode;
117	    }
118	
119	    public String getHouseholdId() {
120	        return this.householdId;
121	    }
122	
123	    public void setHouseholdId(String householdId) {
124	        this.householdId = householdId;
125	    }
126	
127	    public Integer getNamesakeCount() {
128	        return this.namesakeCount;
129	    }
130	
131	    public void setNamesakeCount(Integer namesakeCount) {
132	        this.namesakeCount = namesakeCount;
133	    }
134	
135	    public boolean isBulkSignupWarning() {
136	        return this.bulkSignupWarning;
137	    }
138	
139	    public void setBulkSignupWarning(boolean bulkSignupWarning) {
140	        this.bulkSignupWarning = bulkSignupWarning;
141	    }
142	
143	    protected Set<Pet> getPetsInternal() {
144	        if (this.pets == null) {
145	            this.pets = new HashSet<>();
146	        }
147	        return this.pets;
148	    }
149	
150	    protected void setPetsInternal(Set<Pet> pets) {
151	        this.pets = pets;
152	    }
153	
154	    public List<Pet> getPets() {
155	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
156	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
157	        return Collections.unmodifiableList(sortedPets);
158	    }
159	
160	    public void setPets(List<Pet> pets) {
161	        this.pets = new HashSet<>(pets);
162	    }
163	
164	    public void addPet(Pet pet) {
165	        getPetsInternal().add(pet);
166	        pet.setOwner(this);
167	    }
168	
169	    /**
170	     * Return the Pet with the given name, or null if none found for this Owner.
171	     *
172	     * @param name to test
173	     * @return true if pet name is already in use
174	     */
175	    public Pet getPet(String name) {
176	        return getPet(name, false);
177	    }
178	
179	    /**
180	     * Return the Pet with the given name, or null if none found for this Owner.
181	     *
182	     * @param name to test
183	     * @return true if pet name is already in use
184	     */
185	    public Pet getPet(String name, boolean ignoreNew) {
186	        name = name.toLowerCase();
187	        for (Pet pet : getPetsInternal()) {
188	            if (!ignoreNew || !pet.isNew()) {
189	                String compName = pet.getName();
190	                compName = compName.toLowerCase();
191	                if (compName.equals(name)) {
192	                    return pet;
193	                }
194	            }
195	        }
196	        return null;
197	    }
198	
199	    public Pet getPet(Integer petId) {
200	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
201	    }
202	
203	    @Override
204	    public String toString() {
205	        return new ToStringCreator(this)
206	
207	            .append("id", this.getId())
208	            .append("new", this.isNew())
209	            .append("lastName", this.getLastName())
210	            .append("firstName", this.getFirstName())
211	            .append("address", this.address)
212	            .append("city", this.city)
213	            .append("telephone", this.telephone)
214	            .toString();
215	    }
216	}
