1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	
6	import jakarta.validation.Valid;
7	import net.officefloor.plugin.variable.Out;
8	import org.springframework.samples.petclinic.mapper.OwnerMapper;
9	import org.springframework.samples.petclinic.model.Owner;
10	import org.springframework.samples.petclinic.repository.OwnerRepository;
11	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
12	import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;
13	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
14	import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
15	import org.springframework.validation.annotation.Validated;
16	import org.springframework.web.bind.annotation.RequestBody;
17	
18	@Validated
19	public class BuildOwner {
20	
21	    /** Simple syntactic email check: non-space local part, '@', non-space domain with a dot. */
22	    private static final java.util.regex.Pattern EMAIL =
23	            java.util.regex.Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
24	
25	    public void service(@Valid @RequestBody OwnerFieldsDto request, OwnerMapper ownerMapper,
26	            OwnerRepository ownerRepository, Out<Owner> built, Out<Boolean> sharesHousehold)
27	            throws MissingOwnerFieldsException, InvalidTelephoneException, InvalidEmailException {
28	        List<String> missing = new ArrayList<>();
29	        // Normalize the address up front so the required-field check rejects an address that is
30	        // blank once trimmed/collapsed, and every later step (and the stored value) sees the
31	        // canonical form.
32	        String normalizedAddress = AddressNormalizer.normalize(request.getAddress());
33	        if (isBlank(request.getFirstName())) {
34	            missing.add("firstName");
35	        }
36	        if (isBlank(request.getLastName())) {
37	            missing.add("lastName");
38	        }
39	        if (normalizedAddress.isEmpty()) {
40	            missing.add("address");
41	        }
42	        if (isBlank(request.getCity())) {
43	            missing.add("city");
44	        }
45	        if (isBlank(request.getTelephone())) {
46	            missing.add("telephone");
47	        }
48	        if (!missing.isEmpty()) {
49	            throw new MissingOwnerFieldsException(missing);
50	        }
51	        request.setTelephone(TelephoneNormalizer.normalize(request.getTelephone()));
52	        request.setAddress(normalizedAddress);
53	        request.setEmail(normalizeEmail(request.getEmail()));
54	        Owner owner = ownerMapper.toOwner(request);
55	        // The EFFECTIVE registration date (supplied or defaulted to the server date) must fall on
56	        // a business day: a Saturday or Sunday rolls forward to the next Monday. Every value
57	        // derived from the registration date (e.g. the membership number's year segment, the daily
58	        // create-limit's day) then uses this adjusted date.
59	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
60	        if (registrationDate == null) {
61	            registrationDate = java.time.LocalDate.now();
62	        }
63	        owner.setRegistrationDate(toBusinessDay(registrationDate));
64	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName(), ownerRepository));
65	        built.set(owner);
66	        sharesHousehold.set(Boolean.TRUE.equals(request.getSharesHousehold()));
67	    }
68	
69	    /**
70	     * Roll a registration date off the weekend: a Saturday or Sunday moves forward to the next
71	     * Monday; a weekday is returned unchanged.
72	     */
73	    private static java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
74	        switch (date.getDayOfWeek()) {
75	            case SATURDAY:
76	                return date.plusDays(2);
77	            case SUNDAY:
78	                return date.plusDays(1);
79	            default:
80	                return date;
81	        }
82	    }
83	
84	    /**
85	     * Build a customer code '<CITY3>-<LAST3>-<NNNN>': the upper-cased first three letters of the
86	     * city, a hyphen, the upper-cased first three letters of the last name, a hyphen, then a
87	     * per-city 4-digit zero-padded sequence equal to one more than the number of owners already
88	     * in that city (e.g. 'LON-SMI-0007').
89	     */
90	    private static String nextCustomerCode(String city, String lastName, OwnerRepository ownerRepository) {
91	        String city3 = prefix3(city);
92	        String last3 = prefix3(lastName);
93	        int sequence = 1;
94	        for (Owner existing : ownerRepository.findAll()) {
95	            if (existing.getCity() != null && existing.getCity().equalsIgnoreCase(city)) {
96	                sequence++;
97	            }
98	        }
99	        return String.format("%s-%s-%04d", city3, last3, sequence);
100	    }
101	
102	    /** Upper-cased first three letters (fewer if the value is shorter) of {@code value}. */
103	    private static String prefix3(String value) {
104	        return value.substring(0, Math.min(3, value.length())).toUpperCase(java.util.Locale.ROOT);
105	    }
106	
107	    /** When present, require a syntactically valid address and store it lower-cased; else reject with 400. */
108	    private static String normalizeEmail(String email) throws InvalidEmailException {
109	        if (email == null || email.isBlank()) {
110	            return null;
111	        }
112	        String trimmed = email.trim();
113	        if (!EMAIL.matcher(trimmed).matches()) {
114	            throw new InvalidEmailException(email);
115	        }
116	        return trimmed.toLowerCase(java.util.Locale.ROOT);
117	    }
118	
119	    private static boolean isBlank(String value) {
120	        return value == null || value.isBlank();
121	    }
122	}
