1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	import java.util.Map;
5	
6	/**
7	 * Single home for owner address normalization. The create pipeline's {@link BuildOwner}
8	 * (which stores the canonical form and rejects an address blank after normalization) and
9	 * {@link CheckOwnerHouseholdUnique} (which detects duplicate households and derives the
10	 * shared household id) both go through here, so the stored form and every address
11	 * comparison stay defined in one place.
12	 */
13	final class AddressNormalizer {
14	
15	    private AddressNormalizer() {
16	    }
17	
18	    /** Common street-type abbreviations expanded to their canonical (upper-cased) word. */
19	    private static final Map<String, String> ABBREVIATIONS = Map.of(
20	            "ST", "STREET",
21	            "RD", "ROAD",
22	            "AVE", "AVENUE");
23	
24	    /**
25	     * Canonical stored form of a supplied address: leading/trailing and repeated whitespace
26	     * collapsed to single spaces, upper-cased, then each whitespace-delimited word that is a
27	     * known abbreviation expanded ({@code ST}->{@code STREET}, {@code RD}->{@code ROAD},
28	     * {@code AVE}->{@code AVENUE}). So {@code "  12  main  st "} becomes {@code "12 MAIN STREET"}.
29	     * A {@code null} or all-whitespace address normalizes to the empty string.
30	     */
31	    static String normalize(String address) {
32	        if (address == null) {
33	            return "";
34	        }
35	        String collapsed = address.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
36	        if (collapsed.isEmpty()) {
37	            return "";
38	        }
39	        String[] words = collapsed.split(" ");
40	        StringBuilder sb = new StringBuilder(collapsed.length());
41	        for (int i = 0; i < words.length; i++) {
42	            if (i > 0) {
43	                sb.append(' ');
44	            }
45	            sb.append(ABBREVIATIONS.getOrDefault(words[i], words[i]));
46	        }
47	        return sb.toString();
48	    }
49	}
